const livroPilha=(x,y,w,h,c,cl)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="1.3" fill="${c}" stroke="#1c1917" stroke-width="1.3"/><rect x="${x+w-5}" y="${y+1.5}" width="3.5" height="${h-3}" fill="#fffdf8"/><rect x="${x+w*0.3}" y="${y+h*0.32}" width="${w*0.35}" height="${h*0.36}" fill="${cl}"/>`;

