const olhosRel=(y0,cls,del,cor="#a855f7",nuc="#f5e8ff")=>{const c=0,y=y0;const L=`M${c-8.2},${y-2} L${c-1.3},${y+1.3} L${c-2.3},${y+2.7} Q${c-5.6},${y+1.6} ${c-8.2},${y-2} Z`,R=`M${c+8.2},${y-2} L${c+1.3},${y+1.3} L${c+2.3},${y+2.7} Q${c+5.6},${y+1.6} ${c+8.2},${y-2} Z`;
 return `<g class="${cls}" style="animation-delay:${del}s"><g filter="url(#blurOlho)"><path d="${L}" fill="${cor}" stroke="${cor}" stroke-width="2.4"/><path d="${R}" fill="${cor}" stroke="${cor}" stroke-width="2.4"/></g><path d="${L}" fill="${nuc}"/><path d="${R}" fill="${nuc}"/></g>`;};
const olhoPeq=(x,y,k,cor,del)=>{const L=`M${-8.2*k},${-2*k} L${-1.3*k},${1.3*k} L${-2.3*k},${2.7*k} Q${-5.6*k},${1.6*k} ${-8.2*k},${-2*k} Z`,R=`M${8.2*k},${-2*k} L${1.3*k},${1.3*k} L${2.3*k},${2.7*k} Q${5.6*k},${1.6*k} ${8.2*k},${-2*k} Z`;
 return `<g class="olhoP" style="animation-delay:${del.toFixed(2)}s" transform="translate(${x.toFixed(1)} ${y.toFixed(1)})"><path d="${L}" fill="${cor}"/><path d="${R}" fill="${cor}"/></g>`;};
let sd=7;const rnd=()=>{sd=(sd*16807)%2147483647;return sd/2147483647;};
const PAL=['#ef4444','#3b82f6','#22c55e','#f97316','#22d3ee','#ec4899','#f8fafc'];
const multidao=()=>{let o=[];let n=0;while(o.length<150&&n<5000){n++;const y=82+rnd()*55,x=rnd()*220;const hw=24+(y-62)/78*20;if(Math.abs(x-110)<hw+3)continue;
 const k=.13+(y-82)/55*.3;const d=Math.hypot((x-110)/2.2,(y-70));o.push({x,y,k,d});}
 o.sort((p,q)=>p.d-q.d);const dm=o[o.length-1].d;
 return o.map(e=>olhoPeq(e.x,e.y,e.k,PAL[Math.floor(rnd()*PAL.length)],4.9+1.8*e.d/dm)).join("");};
