<linearGradient id="cone" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f3e8ff" stop-opacity=".05"/><stop offset="1" stop-color="#f3e8ff" stop-opacity=".38"/></linearGradient>
